public async Task<CatalogView> GetCatalogAsync(string userId, CancellationToken ct)
{
    Task<IReadOnlyList<Course>> coursesTask = courses.ListAsync(ct);
    Task<IReadOnlySet<string>> completionsTask = progress.CompletedLessonIdsAsync(userId, ct);

    await Task.WhenAll(coursesTask, completionsTask);
    return CatalogView.From(coursesTask.Result, completionsTask.Result);
}
